import React from 'react';
import { FaThumbsUp, FaComment, FaShare } from 'react-icons/fa';
import { FaLinkedin, FaReddit, FaTwitter } from 'react-icons/fa';

interface PostProps {
  post: {
    id: number;
    author: string;
    role?: string;
    content: string;
    likes: number;
    comments: number;
    shares: number;
    platform: 'linkedin' | 'reddit' | 'twitter';
    timestamp: string;
  };
}

const Post: React.FC<PostProps> = ({ post }) => {
  const getPlatformIcon = () => {
    switch (post.platform) {
      case 'linkedin':
        return <FaLinkedin className="text-primary" />;
      case 'reddit':
        return <FaReddit className="text-secondary" />;
      case 'twitter':
        return <FaTwitter className="text-accent" />;
      default:
        return null;
    }
  };

  const getPlatformColor = () => {
    switch (post.platform) {
      case 'linkedin':
        return 'border-primary';
      case 'reddit':
        return 'border-secondary';
      case 'twitter':
        return 'border-accent';
      default:
        return 'border-gray-200';
    }
  };

  return (
    <div className={`bg-white rounded-lg shadow p-6 border-l-4 ${getPlatformColor()}`}>
      <div className="flex items-start space-x-4">
        <div className="flex-shrink-0">
          <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center">
            {getPlatformIcon()}
          </div>
        </div>
        <div className="flex-1">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-semibold text-gray-900">{post.author}</h3>
              {post.role && <p className="text-sm text-gray-500">{post.role}</p>}
            </div>
            <span className="text-sm text-gray-500">{post.timestamp}</span>
          </div>
          <p className="mt-2 text-gray-700">{post.content}</p>
          <div className="mt-4 flex items-center space-x-6">
            <button className="flex items-center space-x-1 text-gray-500 hover:text-primary">
              <FaThumbsUp />
              <span>{post.likes}</span>
            </button>
            <button className="flex items-center space-x-1 text-gray-500 hover:text-primary">
              <FaComment />
              <span>{post.comments}</span>
            </button>
            <button className="flex items-center space-x-1 text-gray-500 hover:text-primary">
              <FaShare />
              <span>{post.shares}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Post;
